svg.script:
//------Initialize Variables-----------//

//------Parameters
const dashboardMenuRawConfig = {
    GeneralConfig: {
        DashboardID: webMI.query["DashboardID"],
        InitialRangeMethod: webMI.query["InitialRangeMethod"],
        InitialRange: webMI.query["InitialRange"],
        InitialRangeUnit: webMI.query["InitialRangeUnit"],
        RealTimeEnabled:webMI.query["RealTimeEnabled"],
        RealTimeUpdateTime:webMI.query["RealTimeUpdateTime"]
    },
    CacheConfig:{
        CacheEnabled: webMI.query["CacheEnabled"],
        CacheMaxSize: webMI.query["CacheMaxSize"],
        CacheIntervalSize: webMI.query["CacheIntervalSize"]
    },
    CustomFilter: {
        CustomFilterActive: webMI.query["CustomFilterActive"],
        NodeReference: webMI.query["NodeReference"]
    },
    ShiftConfig: {
        AutomaticChange:webMI.query["AutomaticChange"],
        FirstShiftStart: webMI.query["FirstShiftStart"],
        FirstShiftEnd: webMI.query["FirstShiftEnd"],
        SecondShiftStart: webMI.query["SecondShiftStart"],
        SecondShiftEnd: webMI.query["SecondShiftEnd"],
        ThirdShiftStart: webMI.query["ThirdShiftStart"],
        ThirdShiftEnd: webMI.query["ThirdShiftEnd"]
    },
    Appearance: {
        ColorActive: webMI.query["ColorActive"],
        ColorInactive: webMI.query["ColorInactive"],
        FontSizeMenu: webMI.query["FontSizeMenu"],
        FontSizeDatePickers: webMI.query["FontSizeDatePickers"],
        PopUp: webMI.query["PopUpDisplay"]
    },
     DebuggingConfig:{
        DebuggingEnabled: webMI.query["DebuggingEnabled"],
		DebuggingSection: webMI.query["DebuggingSection"]
    },


};

//uI Parameters
const uIElements= {
    Click_Area: ["Click_area_Realtime","Click_area_Historic"],
    Icons: ["play","time"],
    Texts: ["from","to"],
    Combobox: "Initial_Range_Method",
    Click_area_Confirm: "Click_area_Confirm",
    Text_Confirm: "Text_Confirm",
    Shift_Indicator:"ShiftElements",
    Shift_Indicator_Sections: ["Indicator_Shift1","Indicator_Shift2","Indicator_Shift3"]
};

//Initial Range Methods
const initialRangeMethods = [
  { text: 'T{CustomRange}', value: 0 },
  { text: 'T{CurrentHour}', value: 1 },
  { text: 'T{LastHour}', value: 2 },
  { text: 'T{Last_8Hours}', value: 3 },
  { text: 'T{FirstShift}', value: 4 },
  { text: 'T{SecondShift}', value: 5 },
  { text: 'T{ThirdShift}', value: 6 },
  { text: 'T{Today}', value: 7 },
  { text: 'T{Last_7Days}', value: 8 },
  { text: 'T{Yesterday}', value: 9 },
  { text: 'T{CurrentWeek}', value: 10 },
  { text: 'T{LastWeek}', value: 11 },
  { text: 'T{Last_2Weeks}', value: 12 },
  { text: 'T{CurrentMonth}', value: 13 },
  { text: 'T{LastMonth}', value: 14 },
  { text: 'T{Last_6Months}', value: 15 },
  { text: 'T{CurrentYear}', value: 16 }
];


//Time Constants
const ONE_MINUTE = 60 * 1000;
const HALF_HOUR = 30 * ONE_MINUTE;
const ONE_HOUR = 60 * ONE_MINUTE;
const ONE_DAY = 24 * ONE_HOUR;


//------Initial Conditions-----------//
webMI.addOnload(function() {

	//Create dashboard Manager
	const dashboardManager1= new dashboardManager();

	//Create UI Handler
	const userInterfaceHandler1 = new userInterfaceHandler(dashboardMenuRawConfig,uIElements,initialRangeMethods);

	//Initialize UI Handler
	userInterfaceHandler1.initialize(dashboardManager1);

});


//------------------------------------------//
//------------UI Handler Class-------------//

class userInterfaceHandler {

    // Attributes
	uIElements;
    currentConfig; // To store the current configuration state
    updateRequest; // To handle update requests

    // Constructor
    constructor(dashboardMenuRawConfig,uIElements,initialRangeMethods) {
		this.dashboardMenuRawConfig=dashboardMenuRawConfig;
		this.RealTime=dashboardMenuRawConfig.GeneralConfig.RealTimeEnabled=="true" ? true: false;
		this.PreviousMode=this.RealTime==true ? "RealTime": "Hist";
		this.InitialRangeMethod=this.dashboardMenuRawConfig.GeneralConfig.InitialRangeMethod;
		this.ShiftEnabled=this.InitialRangeMethod.includes("Shift")?true:false;
		this.OutofShift;
		this.FirstTime=true;
		this.uIElements=uIElements;
		this.InitialRangeMethods=initialRangeMethods;
		this.InitialRangeMethod=dashboardMenuRawConfig.GeneralConfig.InitialRangeMethod;
		this.InitialRangeMethodOriginal=this.InitialRangeMethod;
		this.InitialRange=dashboardMenuRawConfig.GeneralConfig.InitialRange;
		this.InitialRangeUnit=dashboardMenuRawConfig.GeneralConfig.InitialRangeUnit;
		this.CacheConfig=dashboardMenuRawConfig.CacheConfig;
		this.DebuggingConfig=dashboardMenuRawConfig.DebuggingConfig;
		this.ShiftConfig=dashboardMenuRawConfig.ShiftConfig;
		this.DashboardID=dashboardMenuRawConfig.GeneralConfig.DashboardID;
		this.IgnoreDateChanges=false;
		this.InitialTime;
		this.FinalTime;
        this.currentConfig;
        this.updateRequest;
        this.dashboardManager;
    }

    // Initialize
    async initialize(dashboardManager) {

	   //Store
	   this.dashboardManager=dashboardManager;

       //Calculate time
       await this.calculateTime();

       //Update Date Picker
       this.updateDatePicker();

       //Set Active RT
	   this.setactive(this.dashboardMenuRawConfig.GeneralConfig.RealTimeEnabled=="true" ? 0: 1);

	   //Handle Shift
	   this. shiftIndicatorHandler();

	   //Initialize Triggers
	   this.addListeners();

       //Real Time Trigger
	   this.changeMode(this.RealTime);


	   //Create First Update Request
	   this.createUpdateRequest();

	   //Init Dashboard Manager
	   dashboardManager.initialize(this.updateRequest,false,this.dashboardMenuRawConfig.GeneralConfig.RealTimeEnabled,this.dashboardMenuRawConfig.GeneralConfig.RealTimeUpdateTime,this.dashboardMenuRawConfig,this.OutofShift);

    }


    // Add Listeners
    async addListeners() {
		document.getElementById(this.uIElements.Click_Area[0]).style.cursor = "pointer";
		document.getElementById(this.uIElements.Click_Area[1]).style.cursor = "pointer";
       //Listener Real Time
		webMI.addEvent(this.uIElements.Click_Area[0], "click", (e) => {

			if (this.dashboardMenuRawConfig.GeneralConfig.RealTimeEnabled=="true")				{
				//Back to Original Initial Range
				this.InitialRangeMethod=this.InitialRangeMethodOriginal;

				//Update Final Time
				if(!this.InitialRangeMethod.includes("Shift")){
					this.FinalTime =new Date().getTime();
				}			

				//Real Time Trigger
				this.changeMode(true);

				//Change Colors
				this.setactive(0);
			}
		});

		//Listener Historic
		webMI.addEvent(this.uIElements.Click_Area[1], "click", (e) => {

			//Real Time Trigger
			this.changeMode(false);

			//Open PopUp for selection
			this.openPopUp();

			//Calculate again time
			this.calculateTime();

			//Update Date Picker
			this.updateDatePicker();

			//Change colors
			this.setactive(1);
		});

	    // Global Listener
	    webMI.trigger.connect("datePicker", (e) => {

		// Check Values
		if (e.value && e.value.PreviousMode) {

			//Hist Operation Mode
			if (e.value.Action=="Apply" && e.value.FinalTime && e.value.InitialTime) {

			  // Asign Internal Properties
			  this.FinalTime = new Date(e.value.FinalTime);
			  this.InitialTime = new Date(e.value.InitialTime);
			  this.InitialRangeMethod=e.value.InitialRangeMethod;

			 this.operateText("Update");

			  // Click Apply time range
			  this. shiftIndicatorHandler();
			  this.createUpdateRequest();
			  this.sendUpdateRequests();
			}
			//Real Time Operation Mode
			else if	(e.value.Action=="Cancel" && e.value.PreviousMode=="RealTime") {
				//Back to Original Initial Range
				this.InitialRangeMethod=this.InitialRangeMethodOriginal;

				//Real Time Trigger
				this.changeMode(true);

				//Change Colors
				this.setactive(0);
			}

		}

	    });

	    //Add logic to change automatically shift
	   if (this.ShiftEnabled && (this.ShiftConfig.AutomaticChange=="true")){

			// Note: Checking every second is frequent. For production, consider a longer interval like 60000ms (1 minute).
			setInterval(() => {
				// This logic should only run when the dashboard is in Real-Time mode.
				if (!this.RealTime) {
					return;
				}

				const now = new Date();

				// 1. Check if the current time has passed the end time of the current shift.
				if (now.getTime() > this.FinalTime.getTime()) {

					// Determine the next shift based on the current one.
					let nextShiftMethod;
					switch (this.InitialRangeMethod) {
						case 'FirstShift':
							nextShiftMethod = 'SecondShift';
							break;
						case 'SecondShift':
							nextShiftMethod = 'ThirdShift';
							break;
						case 'ThirdShift':
							nextShiftMethod = 'FirstShift';
							break;
						default:
							// If the current method isn't a shift (e.g., 'Today'), do nothing.
							return;
					}

					// 2. Update the internal state to the new shift.
					this.InitialRangeMethod = nextShiftMethod;

					// Set the new shift as the "original" to return to if mode is toggled.
					this.InitialRangeMethodOriginal = nextShiftMethod;

					// 3. Recalculate InitialTime and FinalTime for the new shift.
					this.calculateTime();

					// 4. Update the UI and request new data.
					this.updateDatePicker();
     				this. shiftIndicatorHandler();
					this.createUpdateRequest();
					this.sendUpdateRequests();
				}
			}, 5000); // Check every 5 seconds.		
	    }


    }

    // Method create Update Rquest
    createUpdateRequest() {
       this.updateRequest = {
			OperationMode: "Hist",
			DashboardID:this.DashboardID,
            initialTime: this.InitialTime,
            finalTime: this.FinalTime,
            customFilterType: "",
            initialRangeMethod:this.InitialRangeMethod,
            cacheConfig: this.CacheConfig,
            DebuggingConfig:this.DebuggingConfig
        };
    }

    // Method to send Update Rquest
    sendUpdateRequests() {

        //Send Update Reguest Dashboard Manager
	   this.dashboardManager.updateRequestHandler(this.updateRequest, this.RealTime);

    }

    //Setactive element
    setactive(ID) {

		//Set active only the current icon
		for (var i=0; i<this.uIElements.Click_Area.length; i++){
			if (i==ID){
				webMI.gfx.setFill(this.uIElements.Icons[i], this.dashboardMenuRawConfig.Appearance.ColorActive);
			}
			else
			{
				webMI.gfx.setFill(this.uIElements.Icons[i],this.dashboardMenuRawConfig.Appearance.ColorInactive);
			}
		}

    }

    //Toggle  Color
    toggleColor(ID) {

		//First Active Color
		webMI.gfx.setFill(ID, dashboardMenuRawConfig.Appearance.ColorActive);

		//Second Inactive Color
		setTimeout(async (e) => {
			webMI.gfx.setFill(ID,dashboardMenuRawConfig.Appearance.ColorInactive);
		},1000);

    }

	//Setactive element
    updateDatePicker() {

		//Fire Picker Updater
        webMI.trigger.fire("com.atvise.datepicker_"+this.DashboardID+"Initial_Date", new Date(this.InitialTime).getTime());
		webMI.trigger.fire("com.atvise.datepicker_"+this.DashboardID+"Final_Date", new Date(this.FinalTime).getTime());
    }

    //Fill Combobox
    fillCombobox(comboxID, comboboxElements) {

		//Excecute
        webMI.trigger.fire("setItems", comboboxElements, comboxID);

        //Set Default Item
        webMI.trigger.fire("setSelectedItem", this.InitialRangeMethod , comboxID);

    }

    // Method to log Request
    requestLogger() {

    }

    //General Calculation Initial Time Final Time
    calculateTime() {

		// Final Time
		let FinalTimeI= new Date();

		// Start
		let InitialTimeI = new Date(FinalTimeI); // Clone Final_Time

		//Auxiliary
		let dayOfWeek=FinalTimeI.getDay();




		switch (this.InitialRangeMethod) {
			case 'CustomRange':
				//Update FinalTime
				this.FinalTime = FinalTimeI;
				//Calculate InitialTime
				InitialTimeI=this.calculateTimeCustomRange()
				break;
			case 'CurrentHour':
				InitialTimeI.setMinutes(0, 0, 0); // Set to the beginning of the current hour
				break;
			case 'LastHour':
				//Update FinalTime
				FinalTimeI.setMinutes(0, 0, 0);
				InitialTimeI.setHours((new Date(FinalTimeI)).getHours() - 1);
				InitialTimeI.setMinutes(0, 0, 0); // Set to the beginning of the last hour
				break;
			case 'Last_8Hours':
				FinalTimeI.setMinutes(0, 0, 0);
				InitialTimeI.setHours((new Date(FinalTimeI)).getHours() - 8);
				InitialTimeI.setMinutes(0, 0, 0);
				break;
			case 'FirstShift': { // Using block scope for const
                const times = this.calculateShiftTimes(this.ShiftConfig.FirstShiftStart, this.ShiftConfig.FirstShiftEnd);
                InitialTimeI = times.initial;
                FinalTimeI = times.final;
				break;
            }
			case 'SecondShift': {
                const times = this.calculateShiftTimes(this.ShiftConfig.SecondShiftStart, this.ShiftConfig.SecondShiftEnd);
                InitialTimeI = times.initial;
                FinalTimeI = times.final;
				break;
            }
			case 'ThirdShift': {
                const times = this.calculateShiftTimes(this.ShiftConfig.ThirdShiftStart, this.ShiftConfig.ThirdShiftEnd);
                InitialTimeI = times.initial;
                FinalTimeI = times.final;
				break;
            }
			case 'Today':
				InitialTimeI.setHours(0, 0, 0, 0); // Start of today
				break;
			case 'Last_7Days':
				InitialTimeI.setDate((new Date(FinalTimeI)).getDate() - 7);
				break;
			case 'Yesterday':
				FinalTimeI.setHours(0, 0, 0, 0);
				InitialTimeI.setDate((new Date(FinalTimeI)).getDate() - 1);
				InitialTimeI.setHours(0, 0, 0, 0); // Start of yesterday
				break;
			case 'CurrentWeek':
				InitialTimeI.setDate((new Date(FinalTimeI)).getDate() - (new Date(FinalTimeI)).getDay());
				InitialTimeI.setHours(0, 0, 0, 0); // Start of the current week
				break;
			case 'LastWeek':

				FinalTimeI.setDate(FinalTimeI.getDate() - dayOfWeek);
				FinalTimeI.setHours(23, 59, 59, 999);

				InitialTimeI.setDate((new Date(FinalTimeI)).getDate() - (new Date(FinalTimeI)).getDay() - 7);
				InitialTimeI.setHours(0, 0, 0, 0); // Start of the last week
				break;
			case 'Last_2Weeks':
				FinalTimeI.setDate(FinalTimeI.getDate() - dayOfWeek - 7); // Shift to the end of the previous complete week
				FinalTimeI.setHours(23, 59, 59, 999);

				InitialTimeI = new Date(FinalTimeI); // Duplicate FinalTimeI to preserve time part
				InitialTimeI.setDate(InitialTimeI.getDate() - 14); // Move back two weeks
				InitialTimeI.setHours(0, 0, 0, 0); // Set to the start of the day

				break;
			case 'CurrentMonth':
				InitialTimeI.setDate(1);
				InitialTimeI.setHours(0, 0, 0, 0); // Start of the current month
				FinalTimeI.setMonth(FinalTimeI.getMonth() + 1, 0); // Set to the last day of the current month
				FinalTimeI.setHours(23, 59, 59, 999); // End of the last day of the month
				break;
			case 'LastMonth':
				InitialTimeI.setMonth(FinalTimeI.getMonth() - 1, 1); // Set to the first day of the last month
				InitialTimeI.setHours(0, 0, 0, 0);
				FinalTimeI.setMonth(FinalTimeI.getMonth(), 0); // Set to the last day of the last month
				FinalTimeI.setHours(23, 59, 59, 999); // End of the last day of the month
				break;
			case 'Last_6Months':
				InitialTimeI.setMonth(FinalTimeI.getMonth() - 6, 1); // Six months ago from the first day of that month
				InitialTimeI.setHours(0, 0, 0, 0);
				// Optionally, set FinalTimeI to the end of the last full month
				FinalTimeI.setDate(0); // Last day of the previous month
				FinalTimeI.setHours(23, 59, 59, 999); // End of the last day of the month
				break;
			case 'CurrentYear':
				InitialTimeI.setFullYear(FinalTimeI.getFullYear(), 0, 1); // Start of the current year
				InitialTimeI.setHours(0, 0, 0, 0);
				// Optionally, set FinalTimeI to the current time or end of the year
				FinalTimeI.setFullYear(FinalTimeI.getFullYear(), 11, 31); // Last day of the year
				FinalTimeI.setHours(23, 59, 59, 999);
				break;
			default:
				console.error('Unsupported InitialRangeMethod:', this.InitialRangeMethod);
				break;
		}

		this.FinalTime = new Date(FinalTimeI);
		this.InitialTime = new Date(InitialTimeI);
	}

	//Calculate Shift times
	calculateShiftTimes(shiftStartString, shiftEndString) {
        const now = new Date();
        let initialTime = new Date(now);
        let finalTime = new Date(now);

        // 1. Parse start and end times from strings
        const start = this.parseTimeString(shiftStartString);
        const end = this.parseTimeString(shiftEndString);

        // 2. Set the initial hours and minutes for today
        initialTime.setHours(start.hours, start.minutes, 0, 0);
        finalTime.setHours(end.hours, end.minutes, 0, 0);

        // 3. Handle overnight shifts (where end time is earlier than start time)
        const isOvernightShift = end.hours < start.hours || 
                                 (end.hours === start.hours && end.minutes < start.minutes);

        if (isOvernightShift) {
            // If the current time is in the early morning part of the shift,
            // it means the shift started on the previous day.
            if (now.getTime() < finalTime.getTime()) {
                initialTime.setDate(initialTime.getDate() - 1);
            } else {
            // Otherwise, the shift ends on the next day.
                finalTime.setDate(finalTime.getDate() + 1);
            }
        }

        // 4. CORE LOGIC: Check if the calculated shift is in the future.
        // If the calculated start time is after the current moment, it hasn't happened yet.
        if (initialTime.getTime() > now.getTime()) {
            // Rewind both start and end times by one day to get the *previous* shift.
            initialTime.setDate(initialTime.getDate() - 1);
            finalTime.setDate(finalTime.getDate() - 1);
        }

        return { initial: initialTime, final: finalTime };
    }


    //Calculate Initial and Final Time for Custom Range
    calculateTimeCustomRange(){

		// Start
		var InitialTimeI = new Date(this.FinalTime); // Clone Final_Time

		switch (this.InitialRangeUnit) {
			case 's': // Seconds
				InitialTimeI.setSeconds(this.FinalTime.getSeconds() - this.InitialRange);
			break;
			case 'min': // Minutes
				InitialTimeI.setMinutes(this.FinalTime.getMinutes() - this.InitialRange);
			break;
			case 'h': // Hours
				InitialTimeI.setHours(this.FinalTime.getHours() - this.InitialRange);
			break;
			case 'day': // Days
				InitialTimeI.setDate(this.FinalTime.getDate() - this.InitialRange);
			break;
			case 'month': // Months
				InitialTimeI.setMonth(this.FinalTime.getMonth() - this.InitialRange);
			break;
			default:
				console.error('Unsupported InitialRangeUnit:', this.InitialRange);
			break;
		}

		return InitialTimeI;
    }

    // Method to change from realTime to Historic
    changeMode(RTactive) {

		const currentTime=new Date().getTime();
	    this.OutofShift = this.FinalTime < currentTime-2000;



		const RTactiveI=(this.dashboardMenuRawConfig.GeneralConfig.RealTimeEnabled=="true"&&  ! (this.OutofShift&&this.ShiftEnabled)) ? RTactive:false;

		//Save Previous mode before changing
		this.PreviousMode=this.RealTime==true? "RealTime" : "Hist";

		//Set RT Active
		this.RealTime=RTactiveI;
    	this.dashboardManager.RealTime=RTactiveI;

		//Show/hide text in RealTime
		if(!RTactiveI){
			this.operateText("Update");
		}

		//Recalculate Real Time
		if(RTactiveI&&!this.FirstTime){

			//Hide elements
			this.operateText("Hide");

			//Update Evaluation time
			this.calculateTime();

			//Create Update Request
			this.createUpdateRequest();

			//Send Update Request
			this.sendUpdateRequests();

		}

		//Send command
        webMI.trigger.fire("RealTime_"+this.DashboardID, RTactiveI);

        //No longer First time
        if(this.FirstTime){
			this.FirstTime=false;
        }
    }

    //Open PopUp
    openPopUp(){


		// Get initialRangeMethods Ready
		webMI.query["InitialRangeMethods"]=JSON.stringify(initialRangeMethods);
		webMI.query["PopUPcacheData"]=JSON.stringify({
																				InitialTime:this.InitialTime,
																				FinalTime:this.FinalTime,
																				InitialRangeMethod:this.InitialRangeMethod,
																				PreviousMode:this.PreviousMode,
																			});



		//Open Pop Up
		webMI.display.openWindow({display:this.dashboardMenuRawConfig.Appearance.PopUp,extern:false,height:350,menubar:false,titlebar:false, modal:true,movable:false,resizable:false,scrollbars:false,status:false,title:"",toolbar:false,width:600,query:webMI.query});

    }

    //Operate Text Elements
    operateText(Action){

		if(Action=="Update"){
			webMI.gfx.setVisible(this.uIElements.Texts[0], true);
			webMI.gfx.setVisible(this.uIElements.Texts[1], true);

			//Set text Accordingly
			webMI.gfx.setText(this.uIElements.Texts[0], "T{From: }" + this.InitialTime.toLocaleString());
			webMI.gfx.setText(this.uIElements.Texts[1], "T{To:}" + this.FinalTime.toLocaleString());
		}
		else if(Action=="Hide"){
			webMI.gfx.setVisible(this.uIElements.Texts[0], false);
			webMI.gfx.setVisible(this.uIElements.Texts[1], false);
		}
    }

    // Parse time string in 24h format (HH:MM) to hours and minutes
    parseTimeString(timeString) {
        // Default values in case of parsing failure
        let hours = 0;
        let minutes = 0;

        try {
            // Check if the timeString is valid
            if (timeString && typeof timeString === 'string') {
                // Split the time string by colon
                const timeParts = timeString.split(':');

                // Parse hours and minutes
                if (timeParts.length >= 2) {
                    hours = parseInt(timeParts[0], 10);
                    minutes = parseInt(timeParts[1], 10);

                    // Validate hours and minutes
                    if (isNaN(hours) || hours < 0 || hours > 24) {
                        console.error('Invalid hours in time string:', timeString);
                        hours = 0;
                    }

                    if (isNaN(minutes) || minutes < 0 || minutes > 59) {
                        console.error('Invalid minutes in time string:', timeString);
                        minutes = 0;
                    }

                    // Special case for 24:00
                    if (hours === 24) {
                        minutes = 0;
                    }
                }
            }
        } catch (error) {
            console.error('Error parsing time string:', timeString, error);
        }

        return { hours, minutes };
    }

    //Handle Shift Indicator
    shiftIndicatorHandler(){
		if(this.ShiftEnabled){

			//Show Shift
			webMI.gfx.setVisible(this.uIElements.Shift_Indicator, true);

			var sectionactive;
			switch (this.InitialRangeMethod) {
						case 'FirstShift':
							sectionactive = 0;
							break;
						case 'SecondShift':
							sectionactive = 1;
							break;
						case 'ThirdShift':
							sectionactive = 2;
							break;
				}

		console.log("Sections============");
		console.log("sectionactive: "+sectionactive);

		//Set active only the current icon
		for (var i=0; i<this.uIElements.Shift_Indicator_Sections.length; i++){
			if (i==sectionactive){
				console.log("Activating section");
				console.log(this.uIElements.Shift_Indicator_Sections[i])
				webMI.gfx.setFill(this.uIElements.Shift_Indicator_Sections[i], this.dashboardMenuRawConfig.Appearance.ColorActive);
			}
			else
			{
				webMI.gfx.setFill(this.uIElements.Shift_Indicator_Sections[i],this.dashboardMenuRawConfig.Appearance.ColorInactive);
			}
		}


		}
		else{
			webMI.gfx.setVisible(this.uIElements.Shift_Indicator, false);

		}
    }

}

//------------------------------------------//
//------------Dashboard Manager Class-------------//

class dashboardManager {
    // Attributes
    ElementsConfig;
    DataRequest;
    UpdateRequest;
    DashboardData;

    // Constructor
    constructor() {
		this.ElementsConfig=new Array();
		this.InitialRangeMethod;
		this.ShiftConfig;
        this.DataRequest;
        this.DataRequestBase;
        this.DataRequestRT;
        this.UniqueNodes;
        this.UniqueNodesDB;
        this.NodesRT=new Array();
        this.UpdateRequest;
        this.ChartTimeRange;
        this.RealTimeEnabled;
        this.RealTimeUpdateTime;
        this.DashboardData;
        this.DashboardDataProcessed;
        this.DashboardDataDirect;
        this.DashboardDataDirectEnabled=true;
        this.DashboardDataRTProcessed;
        this.DashboardDataRTDirect;
        this.DashboardDataRTFinal;
        this.DashboardDataBase;
        this.RealTime;
        this.DataRTDistributed=true;
        this.replacementString="<_::_>"
        this.LoadingDisplay="SYSTEM.LIBRARY.PROJECT.OBJECTDISPLAYS.Advanced_Dashboard.Advanced_Dashboard_Loading_Element";
        this.LoadingDisplayR;
    }


    // Initialize
    async initialize(updateRequest,operationMode,RealTimeEnabled,RealTimeUpdateTime,DashboardMenuRawConfig,OutofShift) {


		//Open Loading Display
		 this.loadingDisplayHandler("Open");

		 //Define Operation Mode
		 this.RealTime=operationMode;

		 //Determine if RT is enabled
		 this.RealTimeEnabled=RealTimeEnabled;

		 //Define RT Updatetime
		 this.RealTimeUpdateTime=RealTimeUpdateTime;

		 //Determine InitialRangeMethod		 
		 this.InitialRangeMethod=DashboardMenuRawConfig.GeneralConfig.InitialRangeMethod;

		 //ShiftConfig
		 this.ShiftConfig=DashboardMenuRawConfig.ShiftConfig;

		 //Set First Update Request
		 this.UpdateRequest=updateRequest;
		 console.log("------------First Update Request---------");
		 console.log(this.UpdateRequest);

		 //Define chartTimeRange
		 this.ChartTimeRange=(this.UpdateRequest.finalTime-this.UpdateRequest.initialTime);

		 //Add Listeners
		 this.addInitialListeners();

		 //Dashboard Ready
		 webMI.trigger.fire("Dashboard_Ready_"+this.DashboardID, true);

		 //Wait for Elements for register
		 setTimeout(async (e) => {

			//Make sure there are Elements
			 if (this.ElementsConfig.length>=1){

				 //Create Data Request
				 await this.createDataRequest();
				 console.log("------------Data Request Ready---------");
				 console.log(this.DataRequest);

				 //Unique nodes in Request
				 this.UniqueNodes= await this.rawDataRequestProcessor(this.DataRequest,"nodesRequest");
				 console.log("------------Unique Nodes---------");
				 console.log(this.UniqueNodes);

				  //Unique nodes in Request
				 this.UniqueNodesDB= await this.rawDataRequestProcessor(this.DataRequest,"nodesRequestDB");
				 console.log("------------Unique Nodes DB---------");
				 console.log(this.UniqueNodesDB);


				 //Create Dashboard Data
				 this.DashboardData= await this.dashboardDataCreatorHandler();
				 this.DashboardDataBase=this.DashboardData;
				 console.log("-----------Dashboard Data--------------");
				 console.log(this.DashboardData);

				 //Distribuite Dashboard Data
				 await this.distributeDashboardData();


				 //Open Loading Display
				 this.loadingDisplayHandler("Close");

				 //Initialize RT
				 this.RealTime= (this.RealTimeEnabled=="true" && !OutofShift) ? true:false;
				 this.addRTListeners();

			 }

		 },500);

    }

