	loadingDisplayHandler(Action) {

		if (Action === "Open") {
			// Open the loading display window
			this.LoadingDisplayR=webMI.display.openWindow({
				display: this.LoadingDisplay,
				extern: false,
				height: 350,
				menubar: false,
				modal: false,
				movable: true,
				resizable: false,
				scrollbars: false,
				status: false,
				title: "T{Dashboard Message}",
				titlebar:false,
				toolbar: false,
				width: 600,
